--region init
function CardProgressionEquipmentSuitFilterDialog:InitHandler()
end

function CardProgressionEquipmentSuitFilterDialog:InitData()
    ---@type Engine.UI.UIArgument
    local argument   = self.controller.Argument
    local parameters = argument.parameters or {}
    self.actionOnClose =  parameters.callBack
    self.selectPart =  parameters.part
    self.bgPosX     =  parameters.bgPosX

    ---@type EquipmentComponent
    local equipComponent  = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    self.ownEquipSuitIds = equipComponent:InitOwnEquipSuitIds()

    local allEquipSuitData = {}
    local equipFilterRows = cardConfMgr:GetAllEquipFilterRow()
    ---@param v TableML.TableFileRow[]
    for i, v in pairs(equipFilterRows) do
        local desc = ParseUtils.ParseLocalizeText(v, "desc")
        desc = string.gsub(desc, "\\n", "\n")
        table.insert(allEquipSuitData, {
            suitId = v:GetPrimaryKey(),
            name = ParseUtils.ParseLocalizeText(v, "name"),
            desc = desc,
            occupationId = parse_number(v, "occupationId"),
            iconPath = ParseUtils.ParsePathName(v, "icon")
        })
    end
    self.allEquipSuitData = allEquipSuitData
end

function CardProgressionEquipmentSuitFilterDialog:InitView()
    if self.bgPosX then
        self.Bg.localPosition = Vector3.New(self.bgPosX, self.Bg.localPosition.y, 0)
    end
end
--endregion init

--region handler
---OnGetFollowerListItemByIndex 随从列表刷新回调
---@param listView SuperScrollView.LoopListView2 @ 列表对象
---@param index number @ c#中的index
---@return SuperScrollView.LoopListViewItem2
function CardProgressionEquipmentSuitFilterDialog:OnGetItemByIndex(listView, index)
    local position = index + 1
    if position < 1 then return nil end

    local suitData = self.allEquipSuitData[position]
    -- 创建cell
    local cell = listView:NewListViewItem("Cell")
    local btnNode = cell.transform:Find('BtnNode')
    SetButtonAction(btnNode, function ()
        self:CellOnClickHandler(position)
    end)
    local imgIcon = btnNode.transform:Find('SuitIconNode/ImgIcon')
    CfUtils.FillImage(imgIcon, suitData.iconPath)
    local textName = btnNode.transform:Find('Layout/TextName')
    CfUtils.FillText(textName, suitData.name)
    
    local textDesc = btnNode.transform:Find('Layout/TextDesc')
    CfUtils.FillText(textDesc, suitData.desc)
    return cell
end

---cell点击回调
function CardProgressionEquipmentSuitFilterDialog:CellOnClickHandler(index)
    --if count <= 0 then
    --    GameUtils.Toast(localize("暂无情绪涂鸦"))
    --    return
    --end

    local equipSuitVo     = self.allEquipSuitData[index]
    local suitId          = checkNumber(equipSuitVo.suitId)
    local ownEquipPartMap = self.ownEquipSuitIds[suitId] or {}
    Events.Broadcast(Constants.EventNames.UICultivateEquipSuitFilterComplete, suitId, ownEquipPartMap)
    UIModule.BackDialog()
end
--endregion handler

--region public
function CardProgressionEquipmentSuitFilterDialog:SetBgPositionX(posX)
    self.Bg.localPosition = Vector3.New(posX, self.Bg.localPosition, 0)
end
--endregion public

--region private
---刷新UI
function CardProgressionEquipmentSuitFilterDialog:RefreshUI()
    self:RefreshGridView()
end 

---刷新列表
function CardProgressionEquipmentSuitFilterDialog:RefreshGridView()
    local count      = #self.allEquipSuitData
    local ScrollView = self.ScrollView
    if not ScrollView.IsListViewInit then
        ScrollView:InitGridView(count, Bind(self, self.OnGetItemByIndex))
        return
    end

    GameUtils.ReloadData(ScrollView, count)
end
--endregion private

return CardProgressionEquipmentSuitFilterDialog